<script setup>
import BookPosition from './BookPosition.vue'
import solusLogo from './assets/solus-logo.svg'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { createAPI } from './api'
import { formatAmount, initialLanguage, normalizeAmounts, translate } from './i18n'
const language = ref(initialLanguage())
const t = text => translate(text, language.value)
const fmt = value => formatAmount(value, language.value)
watch(language, value => {
  document.documentElement.lang = value
  try { localStorage.setItem('solus_language', value) } catch {}
}, { immediate: true })
const pendingReads = ref(0)
const loadingData = computed(() => pendingReads.value > 0)
const api = createAPI()
const localDate = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` }
const authenticated = ref(false), key = ref(''), busy = ref(false), error = ref(''), notice = ref('')
const password = ref(''), newPassword = ref(''), confirmPassword = ref(''), configured = ref(true)
const setupToken = ref(new URLSearchParams(location.hash.slice(1)).get('setup') || '')
if (setupToken.value) history.replaceState(null,'',location.pathname)
const page = ref('Overview'), books = ref([]), bookId = ref(''), period = ref(localDate().slice(0,7))
const accounts = ref([]), summary = ref(null), entries = ref([]), eventCursor = ref(null), schedules = ref([]), scheduleCursor = ref(null)
const plans = ref([]), forecast = ref(null), legacy = ref([]), statement = ref(null), cardId = ref('')
const book = computed(() => books.value.find(b => b.id === bookId.value))
const cards = computed(() => accounts.value.filter(a => a.account_type === 'liability'))
const configuredCards = computed(() => cards.value.filter(a => a.card_calendar))
const card = computed(() => cards.value.find(a => a.id === cardId.value))
const sameCurrencyAccounts = computed(() => accounts.value.filter(a => !a.closed))
const bookForm = reactive({ name: '', kind: 'personal', currency: 'TRY', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone })
const accountForm = reactive({ name: '', account_type: 'asset', currency: 'TRY' })
const tx = reactive({ kind: 'expense', description: '', occurred_on: localDate(), booked_on: '', billed_on: '', amount: '', debit: '', credit: '', installments: 1, first_due_on: '', first_statement_on: '', document_number: '', party: '', related_event_id: '', allocation: '' })
const advanced = ref(false), lines = ref([{ account_id: '', side: 'debit', amount: '' }, { account_id: '', side: 'credit', amount: '' }])
const calendarForm = reactive({ closing_day: '', rule: 'day', due_day: '', due_offset: '', expected_version: 0, effective_period: '', unbilled_account_id: '' })
const statementForm = reactive({ opens_after: '', closes_on: '', due_on: '', stated_balance: '', minimum_due: '', expected_version: 0 })
const planForm = reactive({ kind: 'budget', frequency: 'monthly', name: '', account_id: '', amount: '', starts_on: localDate(), ends_on: '' })
const reversal = reactive({ id: '', reason: '', occurred_on: localDate() })
const paymentItem = ref(null), paymentBank = ref(''), paymentAmount = ref(''), paymentDate = ref(localDate())
const closeDate = ref(''), csvText = ref(''), preview = ref(null)
const business = ref(null), reconciliations = ref([]), reconPreview = ref(null)
const recon = reactive({ account_id:'', opens_after:'', closes_on:'', opening_balance:'', closing_balance:'', original:'' })
const reviewedMatches = reactive({})
const planKey=ref(crypto.randomUUID())
const positions=ref({lots:[],valuations:[]})
const investment=reactive({holding_account_id:'',cash_account_id:'',instrument:'',quantity:'',unit_scale:8,cost:'',fee:'0.00',fee_treatment:'capitalize',fee_account_id:'',occurred_on:localDate()})
const sale=reactive({lot_id:'',cash_account_id:'',gain_account_id:'',loss_account_id:'',quantity:'',proceeds:'',fee:'0.00',fee_account_id:'',occurred_on:localDate()})
const valuation=reactive({account_id:'',instrument:'',as_of:localDate(),value:''})
const nav = ['Overview', 'Journal', 'Accounts', 'Cards & statements', 'Obligations', 'Plans', 'Investments', 'Reports', 'Import & history', 'Period controls', 'Settings']

async function act(fn) {
  if (busy.value) return
  busy.value = true; error.value = ''; notice.value = ''
  try { await fn() } catch (e) { error.value = e.message; if (e.status === 401) authenticated.value = false }
  finally { busy.value = false }
}
async function login() { await act(async () => { await api.login(password.value); password.value=''; authenticated.value = true; await loadBooks() }) }
async function setup() { await act(async()=>{if(newPassword.value!==confirmPassword.value) throw new Error('Passwords do not match.');await api.setup(key.value,newPassword.value,setupToken.value);key.value='';setupToken.value='';password.value=newPassword.value;newPassword.value='';confirmPassword.value='';configured.value=true;await api.login(password.value);password.value='';authenticated.value=true;await loadBooks()}) }
async function changePassword() { await act(async()=>{if(newPassword.value!==confirmPassword.value) throw new Error('Passwords do not match.');await api.changePassword(password.value,newPassword.value);password.value='';newPassword.value='';confirmPassword.value='';authenticated.value=false;notice.value='Password changed. All sessions were revoked; sign in again.'}) }
async function logout() { await act(async () => { await api.logout(); authenticated.value = false; accounts.value = []; entries.value = []; summary.value = null }) }
async function loadBooks() {
  books.value = await api.read('/books')
  if (!bookId.value && books.value.length) bookId.value = (books.value.find(b=>b.revision>0) || books.value[0]).id
  if (bookId.value) await loadBook()
}
async function loadBook() {
  pendingReads.value++
  try {
  if (!bookId.value) return
  const prefix = `/books/${bookId.value}`
  const [a,s,e,o,p,f,b,r,i] = await Promise.all([
    api.read(prefix+'/accounts'), api.read(prefix+`/summary?period=${period.value}`), api.read(prefix+'/events'),
    api.read(prefix+'/schedules'), api.read(prefix+'/plans'), api.read(prefix+`/forecast?period=${period.value}`),
    api.read(prefix+`/business?period=${period.value}`), api.read(prefix+'/reconciliations'),
    api.read(prefix+`/positions?period=${period.value}`),
  ])
  accounts.value = a; summary.value = s; entries.value = e.items; eventCursor.value = e.next_cursor
  schedules.value = o.items; scheduleCursor.value = o.next_cursor; plans.value = p; forecast.value = f
  business.value=b;reconciliations.value=r
  positions.value=i
  if (!cards.value.some(c => c.id === cardId.value)) cardId.value = configuredCards.value[0]?.id || cards.value[0]?.id || ''
  fillCalendar()
  if (card.value?.card_calendar) await loadStatement()
  else statement.value = null
  } finally { pendingReads.value-- }
}
async function save(payload, message = 'Saved. The journal and receipt committed together.') {
  const receipt = await api.write(normalizeAmounts(payload, language.value))
  notice.value = message
  await loadBooks()
  return receipt
}
async function createBook() { await act(async () => { const r = await save({ operation:'book_create', ...bookForm }); bookId.value=r.book_id; bookForm.name=''; await loadBook() }) }
async function createAccount() { await act(async () => { await save({ operation:'account_create', book_id:bookId.value, ...accountForm }); accountForm.name='' }) }
async function post() {
  await act(async () => {
    const postingLines = advanced.value ? lines.value : [{account_id:tx.debit,side:'debit',amount:tx.amount},{account_id:tx.credit,side:'credit',amount:tx.amount}]
    const payload = { operation:'post', book_id:bookId.value, kind:tx.kind, description:tx.description, occurred_on:tx.occurred_on, lines:postingLines }
    if (tx.booked_on) payload.booked_on=tx.booked_on
    if (tx.billed_on) payload.billed_on=tx.billed_on
    if (tx.kind==='card_purchase') { payload.installments=tx.installments; if (tx.first_statement_on) payload.first_statement_on=tx.first_statement_on }
    if (['invoice','bill','loan_disbursement'].includes(tx.kind) && tx.first_due_on) {
      payload.first_due_on=tx.first_due_on; payload.schedule_amount=tx.amount; payload.schedule_currency=accounts.value.find(a=>a.id===tx.debit)?.currency
      payload.installments=tx.installments
    }
    if (tx.related_event_id) payload.related_event_id=tx.related_event_id
    if (tx.allocation) payload.settlements=[{item_id:tx.allocation,amount:tx.amount}]
    if (tx.document_number || tx.party) payload.document={number:tx.document_number || null,party:tx.party || null}
    await save(payload); tx.description=''; tx.amount='';tx.related_event_id='';tx.allocation=''
  })
}
function fillCalendar() {
  const c=card.value?.card_calendar
  Object.assign(calendarForm,{closing_day:c?.closing_day || '',rule:c?.due_offset ? 'offset':'day',due_day:c?.due_day || '',due_offset:c?.due_offset || '',expected_version:c?.version || 0,effective_period:c ? period.value : '',unbilled_account_id:c?.history?.at(-1)?.unbilled_account_id || ''})
}
async function saveCalendar() { await act(async()=>{await save({operation:'card_calendar_put',book_id:bookId.value,account_id:cardId.value,unbilled_account_id:calendarForm.unbilled_account_id || null,closing_day:calendarForm.closing_day,due_day:calendarForm.rule==='day'?calendarForm.due_day:null,due_offset:calendarForm.rule==='offset'?calendarForm.due_offset:null,expected_version:calendarForm.expected_version,effective_period:calendarForm.effective_period || null},'Card dates saved. Existing installment dates remain in their history.')}) }
async function loadStatement() {
  pendingReads.value++
  try {
  if (!card.value?.card_calendar) { statement.value=null; return }
  statement.value=await api.read(`/books/${bookId.value}/statement?account_id=${cardId.value}&period=${period.value}`)
  Object.assign(statementForm,{opens_after:statement.value.opens_after,closes_on:statement.value.closes_on,due_on:statement.value.due_on,stated_balance:statement.value.stated_balance ?? '',minimum_due:statement.value.minimum_due ?? '',expected_version:statement.value.statement_version || 0})
  } finally { pendingReads.value-- }
}
async function saveStatement() { await act(async()=>{ await save({operation:'card_statement_put',book_id:bookId.value,account_id:cardId.value,period:period.value,...statementForm,stated_balance:statementForm.stated_balance || null,minimum_due:statementForm.minimum_due || null},'Statement dates and supplied bank figures saved.'); await loadStatement() }) }
async function reverse() { await act(async()=>{await save({operation:'reverse',book_id:bookId.value,event_id:reversal.id,reason:reversal.reason,occurred_on:reversal.occurred_on}); reversal.id=''; reversal.reason=''}) }
function selectPayment(item) { paymentItem.value=item; paymentAmount.value=item.remaining; page.value='Obligations' }
async function pay() { await act(async()=>{
  const item=paymentItem.value
  const original=await api.read(`/books/${bookId.value}/events?event_id=${item.event_id}`)
  const event=original.items.find(e=>e.id===item.event_id)
  if(!event) throw new Error('Original event unavailable; refresh the obligations list.')
  const principal=event.lines.filter(l=>['asset','liability'].includes(l.account_type))
  if(principal.length!==1) throw new Error('Use the advanced journal for this multi-account obligation.')
  const receiving=principal[0]
  const invoice=event.kind==='invoice'
  await save({operation:'post',book_id:bookId.value,kind:invoice?'invoice_payment':event.kind==='bill'?'bill_payment':'debt_payment',description:`Payment: ${item.description}`,occurred_on:paymentDate.value,
    lines:[{account_id:receiving.account_id,side:invoice?'credit':'debit',amount:paymentAmount.value},{account_id:paymentBank.value,side:invoice?'debit':'credit',amount:paymentAmount.value}],settlements:[{item_id:item.id,amount:paymentAmount.value}]})
  paymentItem.value=null
}) }
async function moreEvents() { await act(async()=>{const r=await api.read(`/books/${bookId.value}/events?before=${eventCursor.value}`); entries.value.push(...r.items); eventCursor.value=r.next_cursor}) }
async function moreSchedules() { await act(async()=>{const r=await api.read(`/books/${bookId.value}/schedules?after=${scheduleCursor.value}`); schedules.value.push(...r.items); scheduleCursor.value=r.next_cursor}) }
async function addPlan() { await act(async()=>{const a=accounts.value.find(a=>a.id===planForm.account_id); await save({operation:'plan_put',book_id:bookId.value,plan_key:planKey.value,expected_version:0,...planForm,currency:a.currency,ends_on:planForm.ends_on || null}); planKey.value=crypto.randomUUID();planForm.name=''; planForm.amount=''}) }
async function recoverReceipt() { await act(async()=>{const r=await api.recover();notice.value=r.status==='cancelled'?'Earlier save was cancelled before posting.':`Earlier command saved. Receipt ${r.command_key}. Review its posted result before recording another occurrence.`;await loadBooks()}) }
async function resolveReceipt() { await act(async()=>{const r=await api.resolve();notice.value=r.status==='cancelled'?'Earlier save was cancelled before posting. You can submit a new action.':'Earlier save already committed. Review its recorded result before submitting another occurrence.';await loadBooks()}) }
async function buyInvestment() { await act(async()=>{await save({operation:'investment_buy',book_id:bookId.value,...investment,fee_account_id:investment.fee_account_id || null});investment.quantity='';investment.cost=''}) }
async function sellInvestment() { await act(async()=>{await save({operation:'investment_sell',book_id:bookId.value,...sale,fee_account_id:sale.fee_account_id || null});sale.quantity='';sale.proceeds=''}) }
async function saveValuation() { await act(async()=>{await save({operation:'valuation_put',book_id:bookId.value,...valuation},'Dated valuation saved. Unrealized movement remains separate from posted income.')}) }
async function togglePlan(p) { await act(async()=>{await save({operation:'plan_put',book_id:bookId.value,plan_key:p.plan_key,expected_version:p.version,kind:p.kind,name:p.name,account_id:p.account_id,amount:p.amount,currency:p.currency,starts_on:p.starts_on,ends_on:p.ends_on,frequency:p.frequency,active:!p.active})}) }
async function closePeriod(reopen=false) { await act(async()=>{await save({operation:'close_period',book_id:bookId.value,through:reopen?null:closeDate.value,expected_revision:book.value.revision},reopen?'Periods reopened; the command remains in audit history.':'Period closed against new postings and corrections.')}) }
async function loadLegacy() { await act(async()=>{legacy.value=(await api.read('/legacy')).items}) }
async function previewImport() { await act(async()=>{preview.value=null;preview.value=await api.read(`/books/${bookId.value}/import-preview`,{method:'POST',body:JSON.stringify({csv:csvText.value})})}) }
async function commitImport() { await act(async()=>{await save({operation:'import_commit',book_id:bookId.value,original:csvText.value,source_hash:preview.value.source_hash},'Import committed atomically; the original and row identities are retained.'); preview.value=null;csvText.value=''}) }
async function previewReconciliation() { await act(async()=>{reconPreview.value=null;Object.keys(reviewedMatches).forEach(k=>delete reviewedMatches[k]);reconPreview.value=await api.read(`/books/${bookId.value}/reconciliation-preview`,{method:'POST',body:JSON.stringify(normalizeAmounts(recon, language.value))})}) }
async function reconcile() { await act(async()=>{await save({operation:'reconcile',book_id:bookId.value,...recon,expected_revision:reconPreview.value.revision,source_hash:reconPreview.value.source_hash,matches:reconPreview.value.rows.map(r=>({row_ref:r.row_ref,event_id:reviewedMatches[r.row_ref]}))},'Statement reconciled: source rows, balances and ledger movements all match.');reconPreview.value=null}) }
function exportJournal() {
  const blob=new Blob([JSON.stringify({book:book.value,scope:'Loaded journal page(s)',events:entries.value},null,2)],{type:'application/json'})
  const url=URL.createObjectURL(blob), a=document.createElement('a');a.href=url;a.download='solus-journal.json';a.click();URL.revokeObjectURL(url)
}
watch(bookId,()=>{ tx.debit='';tx.credit='';cardId.value='';act(loadBook) })
watch(period,()=>act(loadBook))
watch(cardId,()=>{fillCalendar();act(loadStatement)})
onMounted(async()=>{try{configured.value=(await api.read('/auth-status')).configured;await api.resume();authenticated.value=true;await act(loadBooks)}catch{authenticated.value=false}})
</script>

<template>
  <div v-if="!authenticated" class="login-shell"><label class="language-picker">{{ t('Language') }}<select v-model="language" :aria-label="t('Language')"><option value="tr">Türkçe</option><option value="en">English</option></select></label>
    <img class="brandmark" :src="solusLogo" alt="Solus logo" width="128" height="128"><span class="eyebrow">{{ t("YOUR BOOKS, PRECISELY") }}</span><h1>{{ t("Solus") }}</h1>
    <p>{{ t("A clear view of your money.") }}<br>{{ t("Personal finances and business books, in one place.") }}</p>
    <form v-if="configured" class="login-card" @submit.prevent="login"><h2>{{ t("Welcome back") }}</h2><label>{{ t("Password") }}<input :disabled="busy" v-model="password" type="password" autocomplete="current-password" maxlength="256" required></label><button :disabled="busy">{{ t(busy?'Signing in…':'Open your books →') }}</button><small>{{ t("Private financial workspace. Sessions lock after 30 minutes of inactivity.") }}</small></form>
    <form v-else class="login-card" @submit.prevent="setup"><h2>{{ t("Set your Solus password") }}</h2><p v-if="setupToken">{{ t("Your private setup link is ready. Choose a password to protect your books.") }}</p><label v-else>{{ t("Owner API key (first setup only)") }}<input :disabled="busy" v-model="key" type="password" autocomplete="off" required></label><label>{{ t("New password") }}<input :disabled="busy" v-model="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>{{ t("Confirm password") }}<input :disabled="busy" v-model="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button :disabled="busy">{{ t("Set password & open Solus →") }}</button><small>{{ t("Use a unique password or passphrase with at least 12 characters. You can change it in Settings.") }}</small></form>
    <p v-if="error" role="alert" class="error">{{ t(error) }}</p>
    <p v-if="notice" role="status" class="notice">{{ t(notice) }}</p>
  </div>
  <div v-else class="shell">
    <aside><a class="brand" href="/solus/"><img class="brand-logo" :src="solusLogo" alt="" width="64" height="64"><span>{{ t("Solus") }}<small>{{ t("Accounting workspace") }}</small></span></a>
      <nav :aria-label="t('Main navigation')"><button v-for="item in nav" :key="item" :class="{selected:page===item}" @click="page=item">{{ t(item) }}</button></nav>
      <div class="aside-bottom"><span class="dot"></span> {{ t("Connected to Igor") }}<button class="quiet" @click="logout" :disabled="busy">{{ t("Lock workspace") }}</button></div>
    </aside>
    <main :aria-busy="busy"><header><div><span class="eyebrow">{{ t(book?.kind==='business'?'BUSINESS BOOKS':'PERSONAL FINANCES') }}</span><h1>{{ t(page) }}</h1></div><div class="toolbar"><label class="language-picker">{{ t('Language') }}<select v-model="language" :aria-label="t('Language')"><option value="tr">Türkçe</option><option value="en">English</option></select></label><label>{{ t("Book") }}<select :disabled="busy" :aria-label="t('Book')" v-model="bookId"><option value="" disabled>{{ t("Select a book") }}</option><option v-for="b in books" :value="b.id" :key="b.id">{{b.name}}</option></select></label><label>{{ t("Reporting month") }}<input :disabled="busy" v-model="period" type="month" required></label><button class="secondary" @click="act(loadBook)" :disabled="busy">{{ t("Refresh") }}</button></div></header>
      <p v-if="error" class="error" role="alert">{{ t(error) }}</p><p v-if="notice" class="notice" role="status">{{ t(notice) }}</p><div v-if="api.hasPending()"><button class="secondary" @click="recoverReceipt" :disabled="busy">{{ t("Check earlier command receipt") }}</button> <button class="secondary" @click="resolveReceipt" :disabled="busy">{{ t("Resolve earlier save") }}</button><p>{{ t("Resolve returns the saved result if it committed, or cancels the unfinished save so it cannot arrive later. Recorded transactions remain intact.") }}</p></div><div v-if="busy" class="loading-overlay" role="status" aria-live="polite" aria-atomic="true"><div class="loading-card"><span class="loading-spinner" aria-hidden="true"></span><strong>{{ t(loadingData ? 'Loading data…' : 'Working…') }}</strong><span v-if="loadingData">{{book?.name}} · {{period}}</span><small>{{ t('Please wait; the screen will update when this finishes.') }}</small></div></div>
      <section v-if="!books.length || page==='Accounts'" class="panel"><h2>{{ t(books.length?'Add a book':'Start with a book') }}</h2><p>{{ t("Keep personal and business activity in separate books. You name the books and accounts.") }}</p><form @submit.prevent="createBook" class="form-grid"><label>{{ t("Name") }}<input :disabled="busy" v-model="bookForm.name" required maxlength="120" :placeholder="t('Name your book')"></label><label>{{ t("Purpose") }}<select :disabled="busy" :aria-label="t('Purpose')" v-model="bookForm.kind"><option value="personal">{{ t("Personal") }}</option><option value="business">{{ t("Freelance / business") }}</option></select></label><label>{{ t("Currency") }}<input :disabled="busy" v-model="bookForm.currency" required maxlength="3"></label><label>{{ t("Timezone") }}<input :disabled="busy" v-model="bookForm.timezone" required></label><button :disabled="busy">{{ t("Create book") }}</button></form></section>
      <section v-if="page==='Settings'" class="panel"><h2>{{ t("Password & security") }}</h2><button class="secondary" @click="logout" :disabled="busy">{{ t("Lock workspace") }}</button><p>{{ t("Changing your password signs out every Solus browser session. Your accounting records remain intact.") }}</p><form @submit.prevent="changePassword" class="form-grid"><label>{{ t("Current password") }}<input :disabled="busy" v-model="password" type="password" autocomplete="current-password" required maxlength="256"></label><label>{{ t("New password") }}<input :disabled="busy" v-model="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>{{ t("Confirm new password") }}<input :disabled="busy" v-model="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button :disabled="busy">{{ t("Change password & sign out") }}</button></form><p>{{ t("Login attempts are limited. Sessions expire after 30 minutes of inactivity or 8 hours, and authorize only the Solus API. Passwords are stored as salted, memory-hard hashes.") }}</p></section>
      <template v-if="book">
        <div v-if="page==='Overview'">
          <p class="subtitle">{{book.name}} {{ t("· Actuals by occurrence date ·") }} {{period}}</p>
          <div class="stats" v-for="(total,currency) in summary?.totals" :key="currency"><article><span>{{ t("Income ·") }} {{currency}}</span><strong>{{ fmt(total.income) }}</strong></article><article><span>{{ t("Expenses ·") }} {{currency}}</span><strong>{{ fmt(total.expense) }}</strong></article><article class="accent"><span>{{ t("Net income ·") }} {{currency}}</span><strong>{{ fmt(total.net_income) }}</strong></article></div>
          <div v-if="!Object.keys(summary?.totals || {}).length" class="panel empty"><h2>{{ t(accounts.length?"No posted activity this month.":"Your ledger starts here.") }}</h2><p>{{ t(accounts.length?"Your existing balances and commitments appear below. Choose another reporting month to see its actual activity.":"Add accounts, configure your cards, then record an opening balance or your first transaction.") }}</p><button v-if="!accounts.length" @click="page='Accounts'">{{ t("Set up accounts →") }}</button></div>
          <div class="two-col"><BookPosition :report="business" :t="t" :fmt="fmt" /><section class="panel"><h2>{{ t("Upcoming & planned") }}</h2><p>{{ t("Estimates and unpaid obligations are separate from actuals.") }}</p><div v-for="(v,c) in forecast?.net_scheduled" :key="c" class="balance-row"><span>{{ t("Net scheduled ·") }} {{c}}</span><strong>{{ fmt(v) }}</strong></div><div v-for="(item,index) in forecast?.items?.slice(0,8)" :key="index" class="balance-row"><span>{{item.name}}<small>{{ t(item.source) }} · {{item.date || period}}</small></span><strong>{{ fmt(item.amount) }} {{item.currency}}</strong></div><button class="quiet" @click="page='Plans'">{{ t("Manage plans →") }}</button></section></div>
        </div>
        <div v-if="page==='Accounts'"><section class="panel"><h2>{{ t("Add an account") }}</h2><p>{{ t("Assets include cash, bank accounts and receivables. Liabilities include cards, loans and payables. Use expense and income accounts for categories.") }}</p><form @submit.prevent="createAccount" class="form-grid"><label>{{ t("Name") }}<input :disabled="busy" v-model="accountForm.name" required maxlength="120"></label><label>{{ t("Type") }}<select :disabled="busy" :aria-label="t('Type')" v-model="accountForm.account_type"><option v-for="type in ['asset','liability','expense','income','equity']" :value="type" :key="type">{{ t(type) }}</option></select></label><label>{{ t("Currency") }}<input :disabled="busy" v-model="accountForm.currency" required maxlength="3"></label><button :disabled="busy">{{ t("Add account") }}</button></form></section><section class="panel"><h2>{{ t("Your accounts") }}</h2><div v-for="a in accounts" :key="a.id" class="balance-row"><span>{{a.name}}<small>{{ t(a.account_type) }} · {{a.currency}}</small></span><button v-if="a.account_type==='liability'" class="quiet" @click="cardId=a.id;page='Cards & statements'">{{ t(a.card_calendar?'Edit card dates':'Set up card dates') }} →</button></div><p v-if="!accounts.length">{{ t("No accounts yet.") }}</p></section></div>
        <div v-if="page==='Journal'"><section class="panel"><h2>{{ t("Record an occurrence") }}</h2><p>{{ t("Card purchases recognise the full expense once. Installments appear on the statement; payments reduce debt.") }}</p><form @submit.prevent="post"><div class="form-grid"><label>{{ t("Operation") }}<select :disabled="busy" :aria-label="t('Operation')" v-model="tx.kind"><option v-for="k in ['expense','income','card_purchase','transfer','debt_payment','refund','invoice','bill','invoice_payment','bill_payment','credit_note','loan_disbursement','opening','journal','fx','reimbursement']" :value="k" :key="k">{{ t(k.replaceAll('_',' ')) }}</option></select></label><label>{{ t("Description") }}<input :disabled="busy" v-model="tx.description" required maxlength="500"></label><label>{{ t("Occurrence date") }}<input :disabled="busy" v-model="tx.occurred_on" type="date" :max="localDate()" required></label><label>{{ t("Bank booking date (optional)") }}<input :disabled="busy" v-model="tx.booked_on" type="date" :max="localDate()"></label><label v-if="advanced && tx.kind!=='card_purchase'">{{ t("Printed statement date (optional)") }}<input :disabled="busy" v-model="tx.billed_on" type="date"></label></div>
          <label class="checkbox"><input :disabled="busy" v-model="advanced" type="checkbox"> {{ t("Multiple journal lines / tax / FX") }}</label><div v-if="!advanced" class="form-grid"><label>{{ t("Amount") }}<input :disabled="busy" v-model="tx.amount" inputmode="decimal" required :placeholder="language==='tr' ? '0,00' : '0.00'"></label><label>{{ t("Debit account") }}<select :disabled="busy" :aria-label="t('Debit account')" v-model="tx.debit" required><option value="" disabled>{{ t("Select account") }}</option><option v-for="a in sameCurrencyAccounts" :value="a.id" :key="a.id">{{a.name}} · {{ t(a.account_type) }} · {{a.currency}}</option></select></label><label>{{ t("Credit account") }}<select :disabled="busy" :aria-label="t('Credit account')" v-model="tx.credit" required><option value="" disabled>{{ t("Select account") }}</option><option v-for="a in sameCurrencyAccounts" :value="a.id" :key="a.id">{{a.name}} · {{ t(a.account_type) }} · {{a.currency}}</option></select></label></div>
          <div v-else><div v-for="(line,index) in lines" :key="index" class="form-grid"><label>{{ t("Account") }}<select :disabled="busy" :aria-label="t('Account')" v-model="line.account_id" required><option value="" disabled>{{ t("Select account") }}</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Side") }}<select :disabled="busy" :aria-label="t('Side')" v-model="line.side"><option>{{ t("debit") }}</option><option>{{ t("credit") }}</option></select></label><label>{{ t("Amount") }}<input :disabled="busy" v-model="line.amount" inputmode="decimal" required></label><button v-if="lines.length>2" class="quiet" type="button" @click="lines.splice(index,1)">{{ t("Remove line") }}</button></div><button class="quiet" type="button" @click="lines.push({account_id:'',side:'debit',amount:''})">{{ t("+ Add line") }}</button><p>{{ t("Balance debits and credits in every currency. Supply actual FX clearing and tax accounts; rates are never invented.") }}</p></div>
          <div v-if="['card_purchase','invoice','bill','loan_disbursement'].includes(tx.kind)" class="form-grid"><label>{{ t("Installments") }}<input :disabled="busy" v-model.number="tx.installments" type="number" min="1" max="600" required></label><label v-if="tx.kind==='card_purchase'">{{ t("First statement date (optional deferral)") }}<input :disabled="busy" v-model="tx.first_statement_on" type="date"></label><template v-else><label>{{ t("First due date") }}<input :disabled="busy" v-model="tx.first_due_on" type="date" required></label><label>{{ t("Document number") }}<input :disabled="busy" v-model="tx.document_number" maxlength="200"></label><label>{{ t("Customer / supplier") }}<input :disabled="busy" v-model="tx.party" maxlength="200"></label></template></div><div class="form-grid"><label>{{ t("Related original event (optional)") }}<select :disabled="busy" :aria-label="t('Related original event (optional)')" v-model="tx.related_event_id"><option value="">{{ t("No linked original") }}</option><option v-for="e in entries" :key="e.id" :value="e.id">{{e.description}} · {{e.occurred_on}}</option></select></label><label v-if="['credit_note','debt_payment','invoice_payment','bill_payment','reimbursement'].includes(tx.kind)">{{ t("Settle obligation (optional)") }}<select :disabled="busy" :aria-label="t('Settle obligation (optional)')" v-model="tx.allocation"><option value="">{{ t("No allocation") }}</option><option v-for="s in schedules.filter(s=>['scheduled','partial'].includes(s.status))" :key="s.id" :value="s.id">{{s.description}} · {{ fmt(s.remaining) }} {{s.currency}} · {{s.due_on}}</option></select></label></div><button :disabled="busy">{{ t("Post transaction") }}</button></form></section>
          <section v-if="reversal.id" class="panel"><h2>{{ t("Reverse an entry") }}</h2><form @submit.prevent="reverse" class="form-grid"><label>{{ t("Reason") }}<input :disabled="busy" v-model="reversal.reason" required></label><label>{{ t("Correction date") }}<input :disabled="busy" v-model="reversal.occurred_on" type="date" required></label><button :disabled="busy">{{ t("Post reversal") }}</button><button type="button" class="quiet" @click="reversal.id=''">{{ t("Cancel") }}</button></form><p>{{ t("The original stays in the journal. Linked payments must be reversed before their obligation.") }}</p></section>
          <section class="panel"><div class="panel-heading"><h2>{{ t("Posted journal") }}</h2><button class="quiet" @click="exportJournal">{{ t("Export loaded entries") }}</button></div><div v-for="e in entries" :key="e.id" class="entry"><div class="entry-heading"><span><strong>{{e.description}}</strong><small>{{e.occurred_on}} · {{ t(e.kind.replaceAll('_',' ')) }} · {{e.actor}}</small></span><button v-if="!e.reverses_id" class="quiet" @click="reversal.id=e.id">{{ t("Reverse") }}</button></div><div v-for="(l,index) in e.lines" :key="index" class="journal-line"><span>{{l.account}}<small>{{ t(l.side) }}</small></span><span>{{ fmt(l.amount) }} {{l.currency}}</span></div></div><p v-if="!entries.length">{{ t("No posted entries.") }}</p><button v-if="eventCursor" class="secondary" @click="moreEvents" :disabled="busy">{{ t("Load more") }}</button></section>
        </div>
        <div v-if="page==='Cards & statements'"><section class="panel"><h2>{{ t("Your card, your dates") }}</h2><p>{{ t("Add a liability account for each card under Accounts, then set its statement closing and payment rules here.") }}</p><label>{{ t("Card") }}<select :disabled="busy" :aria-label="t('Card')" v-model="cardId"><option value="" disabled>{{ t("Select card") }}</option><option v-for="c in cards" :key="c.id" :value="c.id">{{c.name}} · {{c.currency}}</option></select></label><form v-if="card" @submit.prevent="saveCalendar"><div class="form-grid"><label>{{ t("Unbilled principal account (optional)") }}<select :disabled="busy" v-model="calendarForm.unbilled_account_id"><option value="">{{ t("Native installment schedules only") }}</option><option v-for="a in cards.filter(a=>a.id!==cardId && a.currency===card?.currency)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>{{ t("Statement closing day") }}<input :disabled="busy" v-model.number="calendarForm.closing_day" type="number" min="1" max="31" required></label><label>{{ t("Due-date rule") }}<select :disabled="busy" :aria-label="t('Due-date rule')" v-model="calendarForm.rule"><option value="day">{{ t("Day of month") }}</option><option value="offset">{{ t("Days after closing") }}</option></select></label><label v-if="calendarForm.rule==='day'">{{ t("Payment due day") }}<input :disabled="busy" v-model.number="calendarForm.due_day" type="number" min="1" max="31" required></label><label v-else>{{ t("Days after closing") }}<input :disabled="busy" v-model.number="calendarForm.due_offset" type="number" min="1" max="60" required></label></div><label v-if="calendarForm.expected_version">{{ t("Changes apply from closing month") }}<input :disabled="busy" v-model="calendarForm.effective_period" type="month" required></label><p>{{ t("Short months use their last day. Purchases booked on closing day are included; later bookings enter the next cycle.") }}</p><button :disabled="busy">{{ t("Save card dates") }}</button></form></section>
          <template v-if="statement"><div class="stats"><article><span>{{ t("Billed balance ·") }} {{statement.currency}}</span><strong>{{ fmt(statement.closing_billed_balance) }}</strong><small>{{ t("Closing") }} {{statement.closes_on}}</small></article><article><span>{{ t("Total card principal") }}</span><strong>{{ fmt(statement.total_principal_balance) }}</strong><small>{{ t("Unbilled principal:") }} {{ fmt(statement.unbilled_principal) }} {{statement.currency}}</small></article><article class="accent"><span>{{ t("Payment due") }}</span><strong class="date-stat">{{statement.due_on}}</strong><small>{{ t("Minimum:") }} {{statement.minimum_due === null ? t('Not supplied') : fmt(statement.minimum_due)}}</small></article></div><section class="panel"><h2>{{ t("Statement ·") }} {{period}}</h2><p>{{statement.opens_after}} {{ t("(exclusive) →") }} {{statement.closes_on}} {{ t("(inclusive) ·") }} {{ t(statement.status) }}</p><div v-for="(l,index) in statement.lines" :key="index" class="balance-row"><span>{{l.description}}<small>{{l.date}} · {{ t(l.kind) }}</small></span><strong>{{ fmt(l.amount) }} {{statement.currency}}</strong></div><p v-if="!statement.lines.length">{{ t("No known bookings in this cycle.") }}</p></section><section class="panel"><h2>{{ t("Dates printed on this statement") }}</h2><p>{{ t("Record bank-specific changes and figures for this month. A difference remains visible until you resolve it; a matching total alone does not prove reconciliation.") }}</p><form @submit.prevent="saveStatement"><div class="form-grid"><label>{{ t("Previous close") }}<input :disabled="busy" v-model="statementForm.opens_after" type="date" required></label><label>{{ t("Statement closes") }}<input :disabled="busy" v-model="statementForm.closes_on" type="date" required></label><label>{{ t("Payment due") }}<input :disabled="busy" v-model="statementForm.due_on" type="date" required></label><label>{{ t("Bank statement balance") }}<input :disabled="busy" v-model="statementForm.stated_balance" inputmode="decimal" :placeholder="t('Optional')"></label><label>{{ t("Minimum payment") }}<input :disabled="busy" v-model="statementForm.minimum_due" inputmode="decimal" :placeholder="t('Optional')"></label></div><p v-if="statement.difference!==null">{{ t("Calculated − bank:") }} <strong>{{ fmt(statement.difference) }} {{statement.currency}}</strong></p><button :disabled="busy">{{ t("Save statement details") }}</button></form></section></template></div>
        <div v-if="page==='Obligations'"><section v-if="paymentItem" class="panel"><h2>{{ t("Pay / receive ·") }} {{paymentItem.description}}</h2><form @submit.prevent="pay" class="form-grid"><label>{{ t("Bank / cash account") }}<select :disabled="busy" :aria-label="t('Bank / cash account')" v-model="paymentBank" required><option value="" disabled>{{ t("Select account") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='asset'&&a.currency===paymentItem.currency)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>{{ t("Amount") }}<input :disabled="busy" v-model="paymentAmount" required inputmode="decimal"></label><label>{{ t("Payment date") }}<input :disabled="busy" v-model="paymentDate" type="date" required></label><button :disabled="busy">{{ t("Record actual payment") }}</button><button type="button" class="quiet" @click="paymentItem=null">{{ t("Cancel") }}</button></form></section><section class="panel"><h2>{{ t("Installments, receivables & payables") }}</h2><p>{{ t("Scheduled amounts are commitments. They become payments only when you record an actual transfer.") }}</p><div class="table-scroll"><table><thead><tr><th>{{ t("Occurrence") }}</th><th>{{ t("Due") }}</th><th>{{ t("Amount") }}</th><th>{{ t("Remaining") }}</th><th>{{ t("Status") }}</th><th></th></tr></thead><tbody><tr v-for="s in schedules" :key="s.id"><td>{{s.description}}<small>{{ t("Installment") }} {{s.sequence}}<template v-if="s.statement_on"> {{ t("· Statement") }} {{s.statement_on}}</template></small></td><td>{{s.due_on}}</td><td>{{ fmt(s.amount) }} {{s.currency}}</td><td>{{ fmt(s.remaining) }} {{s.currency}}</td><td><span class="badge">{{ t(s.status) }}</span></td><td><button v-if="['scheduled','partial'].includes(s.status)" class="quiet" @click="selectPayment(s)">{{ t("Record payment") }}</button></td></tr></tbody></table></div><p v-if="!schedules.length">{{ t("No scheduled obligations.") }}</p><button v-if="scheduleCursor" class="secondary" @click="moreSchedules" :disabled="busy">{{ t("Load more") }}</button></section></div>
        <div v-if="page==='Plans'"><section class="panel"><h2>{{ t("Set a budget, recurring estimate or goal") }}</h2><p>{{ t("Plans never silently create posted transactions. Recurring estimates follow your selected frequency and anchor date.") }}</p><form @submit.prevent="addPlan" class="form-grid"><label>{{ t("Type") }}<select :disabled="busy" :aria-label="t('Type')" v-model="planForm.kind"><option>{{ t("budget") }}</option><option>{{ t("recurring") }}</option><option>{{ t("goal") }}</option></select></label><label v-if="planForm.kind==='recurring'">{{ t("Frequency") }}<select :disabled="busy" :aria-label="t('Frequency')" v-model="planForm.frequency"><option>{{ t("monthly") }}</option><option>{{ t("weekly") }}</option><option>{{ t("annual") }}</option></select></label><label>{{ t("Name") }}<input :disabled="busy" v-model="planForm.name" required></label><label>{{ t("Account") }}<select :disabled="busy" :aria-label="t('Account')" v-model="planForm.account_id" required><option value="" disabled>{{ t("Select account") }}</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}} · {{ t(a.account_type) }}</option></select></label><label>{{ t("Amount") }}<input :disabled="busy" v-model="planForm.amount" inputmode="decimal" required></label><label>{{ t("Starts") }}<input :disabled="busy" v-model="planForm.starts_on" type="date" required></label><label>{{ t("Ends (optional)") }}<input :disabled="busy" v-model="planForm.ends_on" type="date"></label><button :disabled="busy">{{ t("Save plan") }}</button></form></section><section class="panel"><h2>{{ t("Your plans") }}</h2><div v-for="p in plans" :key="p.id" class="balance-row"><span>{{p.name}}<small>{{ t(p.kind) }} · {{ fmt(p.amount) }} {{p.currency}} · {{ t(p.active?'active':'paused') }}</small></span><button class="quiet" @click="togglePlan(p)" :disabled="busy">{{ t(p.active?'Pause':'Resume') }}</button></div></section><section class="panel"><h2>{{ t("Forecast & budget comparison ·") }} {{period}}</h2><div v-for="(f,index) in forecast?.items" :key="index" class="balance-row"><span>{{f.name}}<small>{{ t(f.source) }} · {{f.date || period}}</small></span><strong>{{ fmt(f.amount) }} {{f.currency}}<small v-if="f.actual!==undefined">{{ t("Actual") }} {{ fmt(f.actual) }} {{ t("· Remaining") }} {{ fmt(f.remaining) }}</small></strong></div></section></div>
        <div v-if="page==='Import & history'"><section class="panel"><h2>{{ t("Import mapped CSV") }}</h2><p>{{ t("Headers: date, description, kind, amount, debit_account, credit_account, currency, event_ref. event_ref is a stable source occurrence ID, unique within this book. Account names must match your book exactly. Review every row before committing.") }}</p><form @submit.prevent="previewImport"><label>{{ t("CSV contents") }}<textarea :disabled="busy" v-model="csvText" rows="8" required spellcheck="false"></textarea></label><button :disabled="busy">{{ t("Validate & preview") }}</button></form><template v-if="preview"><p>{{preview.rows.length}} {{ t("rows · Source") }} {{preview.source_hash.slice(0,12)}}</p><div class="table-scroll"><table><thead><tr><th>{{ t("Date") }}</th><th>{{ t("Description") }}</th><th>{{ t("Kind") }}</th><th>{{ t("Amount") }}</th></tr></thead><tbody><tr v-for="(r,i) in preview.rows" :key="i"><td>{{r.occurred_on}}</td><td>{{r.description}}</td><td>{{ t(r.kind) }}</td><td>{{ fmt(r.lines[0].amount) }}</td></tr></tbody></table></div><button @click="commitImport" :disabled="busy">{{ t("Commit reviewed import") }}</button></template></section><section class="panel"><h2>{{ t("Preserved financial history") }}</h2><p>{{ t("Historical markdown and prototype records remain intact. They are excluded from these books until mapped to evidenced accounts and occurrences.") }}</p><button class="secondary" @click="loadLegacy" :disabled="busy">{{ t("Inspect historical sources") }}</button><details v-for="l in legacy" :key="l.source"><summary>{{l.source}}<small>{{l.disposition}}</small></summary><pre>{{l.original}}</pre></details></section></div>
        <div v-if="page==='Investments'">
          <section class="panel"><h2>{{ t("Acquire a cost lot") }}</h2><p>{{ t("Supply the actual quantity and native-currency cost from your broker. Create separate holding and cash asset accounts; record currency conversion separately.") }}</p><form @submit.prevent="buyInvestment"><div class="form-grid"><label>{{ t("Holding account") }}<select :disabled="busy" :aria-label="t('Holding account')" v-model="investment.holding_account_id" required><option value="" disabled>{{ t("Select asset") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='asset')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Cash account") }}<select :disabled="busy" :aria-label="t('Investment cash account')" v-model="investment.cash_account_id" required><option value="" disabled>{{ t("Select asset") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='asset')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Instrument / symbol") }}<input :disabled="busy" v-model="investment.instrument" required maxlength="120"></label><label>{{ t("Quantity") }}<input :disabled="busy" v-model="investment.quantity" inputmode="decimal" required></label><label>{{ t("Quantity decimal places") }}<input :disabled="busy" v-model.number="investment.unit_scale" type="number" min="0" max="8" required></label><label>{{ t("Purchase cost") }}<input :disabled="busy" v-model="investment.cost" inputmode="decimal" required></label><label>{{ t("Fee") }}<input :disabled="busy" v-model="investment.fee" inputmode="decimal" required></label><label>{{ t("Fee treatment") }}<select :disabled="busy" :aria-label="t('Fee treatment')" v-model="investment.fee_treatment"><option value="capitalize">{{ t("Add to cost basis") }}</option><option value="expense">{{ t("Expense separately") }}</option></select></label><label>{{ t("Fee expense account") }}<select :disabled="busy" :aria-label="t('Investment fee expense account')" v-model="investment.fee_account_id"><option value="">{{ t("Not needed if capitalized / zero") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='expense')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Acquisition date") }}<input :disabled="busy" v-model="investment.occurred_on" type="date" :max="localDate()" required></label></div><button :disabled="busy">{{ t("Record acquisition") }}</button></form></section>
          <section class="panel"><h2>{{ t("Sell from a specific lot") }}</h2><p>{{ t("You select the lot. Partial sales consume cost proportionally, with any remaining fraction carried to the final sale. Gains, losses and fees use your selected accounts.") }}</p><form @submit.prevent="sellInvestment"><div class="form-grid"><label>{{ t("Cost lot") }}<select :disabled="busy" :aria-label="t('Cost lot')" v-model="sale.lot_id" required><option value="" disabled>{{ t("Select lot") }}</option><option v-for="l in positions.lots" :key="l.id" :value="l.id">{{l.instrument}} · {{ fmt(l.quantity) }} · {{ fmt(l.cost) }} {{l.currency}} · {{l.id.slice(0,8)}}</option></select></label><label>{{ t("Cash account") }}<select :disabled="busy" :aria-label="t('Sale cash account')" v-model="sale.cash_account_id" required><option value="" disabled>{{ t("Select asset") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='asset')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Gain income account") }}<select :disabled="busy" :aria-label="t('Gain income account')" v-model="sale.gain_account_id" required><option value="" disabled>{{ t("Select income") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='income')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Loss expense account") }}<select :disabled="busy" :aria-label="t('Loss expense account')" v-model="sale.loss_account_id" required><option value="" disabled>{{ t("Select expense") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='expense')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Quantity sold") }}<input :disabled="busy" v-model="sale.quantity" inputmode="decimal" required></label><label>{{ t("Gross proceeds") }}<input :disabled="busy" v-model="sale.proceeds" inputmode="decimal" required></label><label>{{ t("Fee") }}<input :disabled="busy" v-model="sale.fee" inputmode="decimal" required></label><label>{{ t("Fee expense account") }}<select :disabled="busy" :aria-label="t('Sale fee expense account')" v-model="sale.fee_account_id"><option value="">{{ t("Not needed if zero") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='expense')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Sale date") }}<input :disabled="busy" v-model="sale.occurred_on" type="date" :max="localDate()" required></label></div><button :disabled="busy">{{ t("Record disposal") }}</button></form></section>
          <section class="panel"><h2>{{ t("Remaining cost lots ·") }} {{period}}</h2><div v-for="l in positions.lots" :key="l.id" class="balance-row"><span>{{l.instrument}} · {{l.account}}<small>{{ fmt(l.quantity) }} {{ t("units · Lot") }} {{l.id.slice(0,8)}}</small></span><strong>{{ fmt(l.cost) }} {{l.currency}}</strong></div><p v-if="!positions.lots.length">{{ t("No remaining tracked cost lots.") }}</p></section>
          <section class="panel"><h2>{{ t("Record a dated market value") }}</h2><p>{{ t("Enter the total market value of all units of one instrument in its holding account. Solus records the observation separately; it never guesses a quote or books unrealized gains as income.") }}</p><form @submit.prevent="saveValuation" class="form-grid"><label>{{ t("Holding account") }}<select :disabled="busy" :aria-label="t('Valuation holding account')" v-model="valuation.account_id" required><option value="" disabled>{{ t("Select asset") }}</option><option v-for="a in accounts.filter(a=>a.account_type==='asset')" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Instrument") }}<input :disabled="busy" v-model="valuation.instrument" required></label><label>{{ t("Observed date") }}<input :disabled="busy" v-model="valuation.as_of" type="date" required :max="localDate()"></label><label>{{ t("Total market value") }}<input :disabled="busy" v-model="valuation.value" inputmode="decimal" required></label><button :disabled="busy">{{ t("Save valuation") }}</button></form><div v-for="(v,index) in positions.valuations" :key="index" class="balance-row"><span>{{v.instrument}}<small>{{v.as_of}} · {{ t(v.status) }}</small></span><strong>{{ fmt(v.value) }} {{v.currency}}<small>{{ t("Unrealized at valuation") }} {{v.unrealized_at_valuation === null ? t('needs review') : fmt(v.unrealized_at_valuation)}}</small></strong></div></section>
        </div>
        <div v-if="page==='Reports'"><BookPosition :report="business" :t="t" :fmt="fmt" /><details class="panel"><summary>{{ t("Technical ledger totals") }}</summary><section class="panel"><h2>{{ t("Raw bookkeeping totals ·") }} {{period}}</h2><p>{{ t("These totals include incomplete migration offsets. Zero difference proves balanced entries, not a complete or correctly classified financial position.") }}</p><div v-for="(sheet,currency) in business?.balance_sheet" :key="currency"><h3>{{currency}}</h3><div v-for="(value,name) in sheet" :key="name" class="balance-row"><span>{{ t(name.replaceAll('_',' ')) }}</span><strong>{{ fmt(value) }}</strong></div></div></section></details><section class="panel"><h2>{{ t("Receivable & payable aging") }}</h2><p>{{ t("Open invoice and bill obligations at month end, after payments and credit notes.") }}</p><div class="table-scroll"><table><thead><tr><th>{{ t("Document") }}</th><th>{{ t("Type") }}</th><th>{{ t("Due") }}</th><th>{{ t("Remaining") }}</th><th>{{ t("Age") }}</th></tr></thead><tbody><tr v-for="(a,index) in business?.aging" :key="index"><td>{{a.description}}<small>{{a.document?.number}} · {{a.document?.party}}</small></td><td>{{ t(a.kind) }}</td><td>{{a.due_on}}</td><td>{{ fmt(a.remaining) }} {{a.currency}}</td><td>{{ t(a.bucket) }} {{ t("days") }}</td></tr></tbody></table></div><p v-if="!business?.aging?.length">{{ t("No open dated receivables or payables.") }}</p></section><section class="panel"><h2>{{ t("Reconciliation history") }}</h2><div v-for="r in reconciliations" :key="r.id" class="balance-row"><span>{{accounts.find(a=>a.id===r.account_id)?.name}}<small>{{r.opens_after}} → {{r.closes_on}}</small></span><strong>{{ t(r.status) }}</strong></div><p v-if="!reconciliations.length">{{ t("No statements reconciled yet.") }}</p></section></div>
        <section v-if="page==='Import & history'" class="panel"><h2>{{ t("Reconcile a bank or card statement") }}</h2><p>{{ t("CSV headers: date,description,amount,event_ref. Positive values increase your asset or card debt; negative values decrease it. This process links existing entries and never posts another copy.") }}</p><form @submit.prevent="previewReconciliation"><div class="form-grid"><label>{{ t("Account") }}<select :disabled="busy" :aria-label="t('Reconciliation account')" v-model="recon.account_id" required><option value="" disabled>{{ t("Select account") }}</option><option v-for="a in accounts.filter(a=>['asset','liability'].includes(a.account_type))" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>{{ t("Previous close") }}<input :disabled="busy" v-model="recon.opens_after" type="date" required></label><label>{{ t("Statement close") }}<input :disabled="busy" v-model="recon.closes_on" type="date" required></label><label>{{ t("Bank opening balance") }}<input :disabled="busy" v-model="recon.opening_balance" inputmode="decimal" required></label><label>{{ t("Bank closing balance") }}<input :disabled="busy" v-model="recon.closing_balance" inputmode="decimal" required></label></div><label>{{ t("Statement rows") }}<textarea :disabled="busy" v-model="recon.original" rows="6" required></textarea></label><button :disabled="busy">{{ t("Preview reconciliation") }}</button></form><template v-if="reconPreview"><p>{{ t("Ledger opening") }} {{ fmt(reconPreview.opening_balance) }} {{ t("→ closing") }} {{ fmt(reconPreview.closing_balance) }} {{reconPreview.currency}}{{ t(". Every row and every ledger movement must match once.") }}</p><form @submit.prevent="reconcile"><div v-for="row in reconPreview.rows" :key="row.row_ref" class="form-grid"><span>{{row.date}} · {{row.description}} · {{ fmt(row.amount) }} {{reconPreview.currency}}</span><label>{{ t("Reviewed ledger match") }}<select :disabled="busy" :aria-label="`Match ${row.row_ref}`" v-model="reviewedMatches[row.row_ref]" required><option value="" disabled>{{ t("Review and select an entry") }}</option><option v-for="candidate in row.candidates" :key="candidate.event_id" :value="candidate.event_id">{{candidate.description}} · {{candidate.dates.join(', ')}} · {{ fmt(candidate.amount) }}</option></select></label></div><button :disabled="busy">{{ t("Confirm reviewed reconciliation") }}</button></form></template></section>
        <section v-if="page==='Period controls'" class="panel"><h2>{{ t("Close completed periods") }}</h2><p>{{ t("Closed through:") }} <strong>{{ t(book.closed_through || 'No period closed') }}</strong>{{ t(". Revision") }} {{book.revision}}.</p><p>{{ t("Closing blocks new postings and corrections dated on or before the cutoff. Reopening is explicit and leaves an audit receipt.") }}</p><form @submit.prevent="closePeriod()" class="form-grid"><label>{{ t("Close through") }}<input :disabled="busy" v-model="closeDate" type="date" required :max="localDate()"></label><button :disabled="busy">{{ t("Close period") }}</button><button v-if="book.closed_through" type="button" class="secondary" @click="closePeriod(true)" :disabled="busy">{{ t("Reopen periods") }}</button></form></section>
      </template>
      <footer>{{ t("Solus · Exact money. Preserved history.") }} <span>{{ t("Amounts stay in their native currency.") }}</span></footer>
    </main>
  </div>
</template>
